// Helper to get stats including ORCID cross-reference data
function getBCStats() {
  const total = BC_FACULTY_DATA.length;
  const recruiting = BC_FACULTY_DATA.filter(f => f.status === "recruiting").length;
  const inquire = BC_FACULTY_DATA.filter(f => f.status === "inquire").length;
  const stale = BC_FACULTY_DATA.filter(f => f.status === "stale" || f.isStale).length;
  const full = BC_FACULTY_DATA.filter(f => f.status === "full").length;
  const future = BC_FACULTY_DATA.filter(f => f.status === "future").length;
  const departments = new Set(BC_FACULTY_DATA.map(f => f.department)).size;

  // ORCID Cross-Referencing Stats
  const orcidActive = BC_FACULTY_DATA.filter(f => f.orcid && f.orcid.researchActive).length;
  const orcidInactive = BC_FACULTY_DATA.filter(f => f.orcid && !f.orcid.researchActive).length;

  return { total, recruiting, inquire, stale, full, future, departments, orcidActive, orcidInactive };
}

// Global browser and Node environment exports
if (typeof window !== "undefined") {
  window.BC_SCHOOLS = BC_SCHOOLS;
  window.BC_DEPARTMENTS = BC_DEPARTMENTS;
  window.BC_FACULTY_DATA = BC_FACULTY_DATA;
  window.getBCStats = getBCStats;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    BC_SCHOOLS,
    BC_DEPARTMENTS,
    BC_FACULTY_DATA,
    getBCStats
  };
}
